import { Dialog } from '@gravity-ui/uikit';

export interface ConfirmDialogProps {
  open: boolean;
  title: string;
  text: string;
  confirmText?: string;
  cancelText?: string;
  onConfirm: () => void;
  onCancel: () => void;
}

export function ConfirmDialog({
  open,
  title,
  text,
  confirmText = 'Подтвердить',
  cancelText = 'Отменить',
  onConfirm,
  onCancel,
}: ConfirmDialogProps) {
  return (
    <Dialog
      open={open}
      onClose={onCancel}
      onEnterKeyDown={onConfirm}
      size="s"
      initialFocus="cancel"
      aria-labelledby="confirm-dialog-title"
      qa="confirm-dialog"
    >
      <Dialog.Header caption={title} id="confirm-dialog-title" />
      <Dialog.Body>{text}</Dialog.Body>
      <Dialog.Footer
        textButtonApply={confirmText}
        textButtonCancel={cancelText}
        onClickButtonApply={onConfirm}
        onClickButtonCancel={onCancel}
        propsButtonApply={{ qa: 'confirm-dialog-apply' }}
        propsButtonCancel={{ qa: 'confirm-dialog-cancel' }}
      />
    </Dialog>
  );
}
EOF
cat > src/App.tsx <<'EOF'
import { useState } from 'react';
import { Button, Flex, Text } from '@gravity-ui/uikit';

import { ConfirmDialog } from './ConfirmDialog';

type Result = 'confirmed' | 'cancelled' | null;

export function App() {
  const [open, setOpen] = useState(false);
  const [result, setResult] = useState<Result>(null);

  const handleConfirm = () => {
    setResult('confirmed');
    setOpen(false);
  };

  const handleCancel = () => {
    setResult('cancelled');
    setOpen(false);
  };

  return (
    <Flex direction="column" gap={3} alignItems="flex-start" style={{ padding: 24 }}>
      <Button view="action" size="l" onClick={() => setOpen(true)} qa="open-confirm-dialog">
        Удалить элемент
      </Button>

      {result === 'confirmed' && (
        <Text color="positive" qa="confirm-result">
          Действие подтверждено
        </Text>
      )}
      {result === 'cancelled' && (
        <Text color="secondary" qa="confirm-result">
          Действие отменено
        </Text>
      )}

      <ConfirmDialog
        open={open}
        title="Подтвердите действие"
        text="Вы действительно хотите удалить этот элемент? Это действие нельзя отменить."
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </Flex>
  );
}
EOF
